import{_ as r,c as o,o as i,ae as t}from"./chunks/framework.DMK_uHmU.js";const c=JSON.parse('{"title":"User Profile Groups Management Guide","description":"","frontmatter":{},"headers":[],"relativePath":"Administration/Manage/Users/user-groups.md","filePath":"Administration/Manage/Users/user-groups.md"}'),s={name:"Administration/Manage/Users/user-groups.md"};function a(n,e,l,u,p,g){return i(),o("div",null,e[0]||(e[0]=[t('<h1 id="user-profile-groups-management-guide" tabindex="-1">User Profile Groups Management Guide <a class="header-anchor" href="#user-profile-groups-management-guide" aria-label="Permalink to &quot;User Profile Groups Management Guide&quot;">​</a></h1><h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h2><p>The User Profile Groups component allows administrators to manage a user&#39;s membership in organizational groups. Groups are a powerful way to organize users and control access to content and features based on organizational structure, departments, roles, or projects.</p><h2 id="accessing-group-management" tabindex="-1">Accessing Group Management <a class="header-anchor" href="#accessing-group-management" aria-label="Permalink to &quot;Accessing Group Management&quot;">​</a></h2><p>The Group Management component is accessible to users with specific roles:</p><ul><li>Admin</li><li>Content</li><li>Manager</li></ul><p>To access this component:</p><ol><li>Navigate to a user profile page (<code>/user/profile/[user_id]</code>)</li><li>Click on the &quot;Groups&quot; tab in the left navigation menu</li></ol><h2 id="group-management-interface-overview" tabindex="-1">Group Management Interface Overview <a class="header-anchor" href="#group-management-interface-overview" aria-label="Permalink to &quot;Group Management Interface Overview&quot;">​</a></h2><p>The Group Management interface displays a list of groups to which the user belongs. Each group entry shows:</p><ol><li><strong>Group Avatar</strong>: Displays the group&#39;s initials in a circular badge</li><li><strong>Group Name</strong>: The full name of the group</li><li><strong>Group Description</strong>: A brief explanation of the group&#39;s purpose</li><li><strong>Action Button</strong>: Edit/pencil icon to modify group settings</li></ol><p>The header area includes:</p><ul><li>A users icon indicating group management</li><li>A &quot;Manage Group Memberships&quot; title</li><li>A brief description: &quot;Assign this user to groups for access to content&quot;</li></ul><h2 id="understanding-user-groups" tabindex="-1">Understanding User Groups <a class="header-anchor" href="#understanding-user-groups" aria-label="Permalink to &quot;Understanding User Groups&quot;">​</a></h2><p>Groups serve several important purposes within the system:</p><ol><li><strong>Content Access Control</strong>: Groups determine which content users can view and interact with</li><li><strong>Feature Access</strong>: Some features may be restricted to members of specific groups</li><li><strong>Organizational Structure</strong>: Groups reflect reporting structures and departmental organization</li><li><strong>Communication</strong>: Groups can be used for targeted messaging and notifications</li><li><strong>Permission Management</strong>: Apply permissions to multiple users simultaneously</li></ol><h2 id="viewing-group-memberships" tabindex="-1">Viewing Group Memberships <a class="header-anchor" href="#viewing-group-memberships" aria-label="Permalink to &quot;Viewing Group Memberships&quot;">​</a></h2><p>When you access the Groups tab for an existing user, the system automatically loads all groups to which the user belongs. The groups are displayed in a list format with the following information:</p><ol><li><strong>Group Initials</strong>: Displayed within a circular avatar</li><li><strong>Group Name</strong>: The primary identifier for the group</li><li><strong>Group Description</strong>: Additional context about the group&#39;s purpose or members</li></ol><p>If the user does not belong to any groups, a message will be displayed: &quot;There are no group memberships for this user.&quot;</p><h2 id="managing-group-memberships" tabindex="-1">Managing Group Memberships <a class="header-anchor" href="#managing-group-memberships" aria-label="Permalink to &quot;Managing Group Memberships&quot;">​</a></h2><h3 id="adding-a-user-to-groups" tabindex="-1">Adding a User to Groups <a class="header-anchor" href="#adding-a-user-to-groups" aria-label="Permalink to &quot;Adding a User to Groups&quot;">​</a></h3><p>To add a user to one or more groups:</p><ol><li>From the Groups tab, locate the &quot;Smart Group Builder&quot; button (shown when no groups exist)</li><li>Click the button to navigate to the Group List View (<code>/groups/GroupListView</code>)</li><li>In the Group List View: <ul><li>Find the group you want to add the user to</li><li>Click the edit button for that group</li><li>Use the Smart Group Builder to add the user to the group</li><li>Save the group changes</li></ul></li></ol><h3 id="removing-a-user-from-groups" tabindex="-1">Removing a User from Groups <a class="header-anchor" href="#removing-a-user-from-groups" aria-label="Permalink to &quot;Removing a User from Groups&quot;">​</a></h3><p>Group membership is managed through the Smart Group Builder:</p><ol><li>From the Groups tab, find the group you want to remove the user from</li><li>Click the pencil/edit icon next to the group name</li><li>The Smart Group Builder dialog will open</li><li>Use the Smart Group Builder interface to remove the user</li><li>Save the changes</li></ol><h3 id="editing-group-details" tabindex="-1">Editing Group Details <a class="header-anchor" href="#editing-group-details" aria-label="Permalink to &quot;Editing Group Details&quot;">​</a></h3><p>While viewing a user&#39;s groups, you can directly access the group settings:</p><ol><li>Click the pencil/edit icon next to any group</li><li>The Smart Group Builder dialog will open</li><li>Modify group settings as needed: <ul><li>Group name</li><li>Group description</li><li>Membership rules</li><li>Member list</li></ul></li><li>Save your changes</li><li>The user&#39;s group list will automatically update to reflect any changes</li></ol><h2 id="smart-group-builder" tabindex="-1">Smart Group Builder <a class="header-anchor" href="#smart-group-builder" aria-label="Permalink to &quot;Smart Group Builder&quot;">​</a></h2><p>The Smart Group Builder is a powerful tool for managing group configurations:</p><ol><li><strong>Access</strong>: Click the pencil icon next to any group or the &quot;Smart Group Builder&quot; button</li><li><strong>Interface</strong>: A dialog opens showing comprehensive group management options</li><li><strong>Functions</strong>: <ul><li>Define group membership rules</li><li>Add/remove individual members</li><li>Set group properties</li><li>Configure group permissions</li></ul></li></ol><p>When using the Smart Group Builder from the user&#39;s Groups tab, it will focus on the selected group with the current user pre-selected for membership operations.</p><h2 id="group-based-access-control" tabindex="-1">Group-Based Access Control <a class="header-anchor" href="#group-based-access-control" aria-label="Permalink to &quot;Group-Based Access Control&quot;">​</a></h2><p>Understanding how groups affect user access is essential:</p><ol><li><strong>Content Filtering</strong>: Users can only see content shared with groups they belong to</li><li><strong>Feature Access</strong>: Some system features may be restricted to specific groups</li><li><strong>Administrative Boundaries</strong>: Group administrators may only manage users within their groups</li><li><strong>Reporting Hierarchies</strong>: Groups often reflect organizational reporting structures</li></ol><p>When assigning a user to groups, consider:</p><ul><li>What content should this user access?</li><li>Which teams or departments does this user belong to?</li><li>What level of permissions should this user have?</li><li>Are there project-specific groups that would be relevant?</li></ul><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><p><strong>Issue</strong>: Groups not loading</p><ul><li>Check network connectivity</li><li>Verify the user ID is valid</li><li>Ensure your administrative account has permission to view groups</li><li>Review error messages in the toast notifications</li></ul><p><strong>Issue</strong>: Cannot edit a group</p><ul><li>Verify you have administrative rights for the group</li><li>Check if the group is a system group (cannot be modified)</li><li>Ensure the Smart Group Builder service is available</li></ul><p><strong>Issue</strong>: User not appearing in a group after being added</p><ul><li>The group may have conditional membership rules that the user doesn&#39;t satisfy</li><li>Group cache may need to be refreshed</li><li>Check for conflicting group membership rules</li></ul><p><strong>Issue</strong>: &quot;Services Error&quot; message</p><ul><li>Note the error code provided in the message</li><li>Check network connectivity</li><li>Contact system administrator if the issue persists</li></ul><p><strong>Issue</strong>: Cannot find the Smart Group Builder button</p><ul><li>Navigate directly to <code>/groups/GroupListView</code></li><li>Verify you have the required permissions</li><li>Check if your account has restrictions on group management</li></ul><hr><p>For more advanced group management scenarios, refer to the Group Administration Documentation.</p>',52)]))}const d=r(s,[["render",a]]);export{c as __pageData,d as default};
